export function useProjectText() {
  const { locale } = usePreferences()
  return useCallback((source: string): string => {
    if (locale === 'es') return source
    if (projectCopy[source]) return projectCopy[source]
    const monthNames: Record<string, string> = { ene: 'Jan', feb: 'Feb', mar: 'Mar', abr: 'Apr', may: 'May', jun: 'Jun', jul: 'Jul', ago: 'Aug', sep: 'Sep', oct: 'Oct', nov: 'Nov', dic: 'Dec' }
    return source.replace(/^(ene|feb|mar|abr|may|jun|jul|ago|sep|oct|nov|dic) (\d{4})$/, (_, month: string, year: string) => `${monthNames[month]} ${year}`)
  }, [locale])
}
